def findAlmostEqualSubstring(s: str, t: str) -> int:
    n, m = len(s), len(t)
    if m > n:
        return -1

    def z_function(a):
        L = len(a)
        z = [0] * L
        l = r = 0
        for i in range(1, L):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < L and a[z[i]] == a[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        return z

    # pre[i]: longest common prefix of s[i:] and t
    z1 = z_function(t + '#' + s)
    # suf of window [i, i+m): longest common suffix of s[:i+m] and t,
    # i.e. the LCP of reversed s starting at n-(i+m) with reversed t
    z2 = z_function(t[::-1] + '#' + s[::-1])

    for i in range(n - m + 1):
        p = z1[m + 1 + i]
        q = z2[m + 1 + (n - i - m)]
        if p + q >= m - 1:
            return i
    return -1
